const productWeights={"moringa-powder":100,"curry-leaves":30,"black-tea":100,"moringa-soap":95,"combo-pack":130,"gift-pack":325,"moringa-400g":400,"moringa-200g":200,"moringa-soap-combo":195};function addProductToCart(o,a,t,r){if(window.Cart&&window.Cart.add){const d=productWeights[o]||100;window.Cart.add({id:o,name:a,price:t,image:r,weight:d,quantity:1})}}window.addProductToCart=addProductToCart;
